-- Somente banco isolado; cópias temporárias neutralizam gates nelas. Rollback integral.
begin;
set local app.auvo_sync_write='true';
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(40);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('18593000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s185-conflito@test.local',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('18593000-0000-4000-8000-000000000001','superadmin','Gestor sintético',true);
insert into pcm.clientes(id,nome,created_by) values ('18593000-0000-4000-8000-00000000000a','Cliente A','18593000-0000-4000-8000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('18593000-0000-4000-8000-000000000001','integracao.reconciliar','18593000-0000-4000-8000-00000000000a');
insert into pcm.chamados(id,numero,cliente_id,titulo,created_by,sso_encerrado_em) values ('18593000-0000-4000-8000-000000000011','CH-S185-CONFLITO','18593000-0000-4000-8000-00000000000a','Chamado A','18593000-0000-4000-8000-000000000001',now());
insert into pcm.ordens_servico(id,client_id,titulo,categoria,status,origem,created_by,chamado_id,auvo_task_id) values ('18593000-0000-4000-8000-000000000021','18593000-0000-4000-8000-00000000000a','OS sintética','corretiva','finalizado','auvo','18593000-0000-4000-8000-000000000001','18593000-0000-4000-8000-000000000011',18593000);
select set_config('request.jwt.claims','{"sub":"18593000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}',true);
do $test$
declare v_original text; v_copia text; v_nome text; v_sig text; v_gate text;
begin
 foreach v_nome in array array['sso_registrar_conflito_webhook_chamado','sso_listar_os_reconciliacao','sso_listar_conflitos_webhook_chamado','sso_listar_conflitos_webhook_autorizado','sso_resolver_conflito_webhook_chamado'] loop
  v_sig:=case when v_nome='sso_registrar_conflito_webhook_chamado' then '(uuid,bigint,text)' when v_nome in ('sso_listar_conflitos_webhook_chamado','sso_listar_conflitos_webhook_autorizado') then '(uuid,uuid,timestamptz,uuid,integer)' when v_nome='sso_resolver_conflito_webhook_chamado' then '(uuid,uuid,uuid,timestamptz,bigint,text,boolean)' else '(uuid,uuid,integer)' end;
  v_gate:=case when v_nome='sso_registrar_conflito_webhook_chamado' then 'sso_conflito_webhook_chamado_gate' when v_nome='sso_listar_conflitos_webhook_autorizado' then 'sso_consulta_conflitos_webhook_gate' when v_nome='sso_resolver_conflito_webhook_chamado' then 'sso_resolucao_conflito_webhook_gate' else 'reconciliacao_outbox_gate' end;
  select pg_get_functiondef(('pcm.'||v_nome||v_sig)::regprocedure) into v_original;
  v_copia:=replace(v_original,'FUNCTION pcm.'||v_nome||'(', 'FUNCTION pg_temp.'||v_nome||'(');
  v_copia:=replace(v_copia,'if not coalesce((select habilitado from pcm.'||v_gate||' where id),false) then','if false then');
  v_copia:=replace(v_copia,'if not coalesce((select g.habilitado from pcm.'||v_gate||' g where g.id),false) then','if false then');
  if v_nome='sso_listar_conflitos_webhook_autorizado' then v_copia:=replace(v_copia,'pcm.sso_listar_conflitos_webhook_chamado(p_cliente_id','pg_temp.sso_listar_conflitos_webhook_chamado(p_cliente_id'); end if;
  if v_copia=v_original or position('if false then' in v_copia)=0 then raise exception 'falha ao criar cópia %',v_nome; end if;
  execute v_copia;
 end loop;
end $test$;
select lives_ok($$select pg_temp.sso_registrar_conflito_webhook_chamado('18593000-0000-4000-8000-000000000021',18593000,'em_execucao')$$,'conflito confirmado é registrado');
select lives_ok($$select pg_temp.sso_registrar_conflito_webhook_chamado('18593000-0000-4000-8000-000000000021',18593000,'em_execucao')$$,'reentrega não falha');
select is((select count(*)::int from pcm.reconciliacao_webhook_chamado_conflitos where os_id='18593000-0000-4000-8000-000000000021'),1,'reentrega da condição não cria duplicata');
select is((select count(*)::int from audit.events where entity_id='18593000-0000-4000-8000-000000000021' and action='integracao.conflito_webhook_chamado'),1,'registro inicial é auditado sem duplicar auditoria no retry');
select throws_ok($$select pg_temp.sso_registrar_conflito_webhook_chamado('18593000-0000-4000-8000-000000000021',18593001,'em_execucao')$$,'23514','conflito_nao_confirmado','task diferente é rejeitada');
select is((select classificacao from pg_temp.sso_listar_os_reconciliacao('18593000-0000-4000-8000-00000000000a',null,50) where id='18593000-0000-4000-8000-000000000021'),'conflito_chamado_encerrado','painel existente classifica conflito');
select is((select status_remoto from pg_temp.sso_listar_conflitos_webhook_chamado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',null,null,50)),'em_execucao','leitura detalha status remoto');
select is((select count(*)::int from pg_temp.sso_listar_conflitos_webhook_chamado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',(select criado_em from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),50)),0,'cursor não repete conflito');
select throws_ok($$select * from pg_temp.sso_listar_conflitos_webhook_chamado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',now(),null,50)$$,'22023','paginacao_invalida','cursor incompleto é rejeitado');
select throws_ok($$select * from pg_temp.sso_listar_conflitos_webhook_chamado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000099',null,null,50)$$,'42501','os_nao_encontrada_ou_sem_acesso','OS ausente não expõe dados');
select ok(not has_function_privilege('authenticated','pcm.sso_listar_conflitos_webhook_chamado(uuid,uuid,timestamptz,uuid,integer)','execute'),'consulta real continua privada');
select throws_ok($$select * from pcm.sso_listar_conflitos_webhook_chamado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',null,null,50)$$,'55000','reconciliacao_bloqueada','núcleo permanece bloqueado');
select throws_ok($$select * from pcm.sso_listar_os_reconciliacao('18593000-0000-4000-8000-00000000000a',null,50)$$,'55000','reconciliacao_bloqueada','lista existente permanece bloqueada');
select is((select status_remoto from pg_temp.sso_listar_conflitos_webhook_autorizado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',null,null,50)),'em_execucao','wrapper mediado lista conflito autorizado');
select throws_ok($$select * from pcm.sso_listar_conflitos_webhook_autorizado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',null,null,50)$$,'55000','consulta_conflito_bloqueada','wrapper operacional está fechado');
select ok(has_function_privilege('authenticated','pcm.sso_listar_conflitos_webhook_autorizado(uuid,uuid,timestamptz,uuid,integer)','execute') and not has_function_privilege('anon','pcm.sso_listar_conflitos_webhook_autorizado(uuid,uuid,timestamptz,uuid,integer)','execute'),'somente autenticado recebe wrapper');
select is((select habilitado from pcm.sso_consulta_conflitos_webhook_gate where id),false,'gate de mediação permanece fechado');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'finalizado',false)$$,'22023','resolucao_invalida','sem atestado explícito não resolve');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'finalizado',true)$$,'23514','status_ainda_divergente','status diferente não é resolvido');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at)-interval '1 second' from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'finalizado',true)$$,'40001','origem_alterada','fotografia antiga não resolve');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593001,'finalizado',true)$$,'40001','origem_alterada','task divergente não resolve');
update pcm.ordens_servico set status='em_execucao' where id='18593000-0000-4000-8000-000000000021';
select lives_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'em_execucao',true)$$,'status coerente e conferência atestada permitem decisão');
select lives_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'em_execucao',true)$$,'retry idêntico é idempotente');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'cancelado',true)$$,'23505','request_id_conflitante','requestId com outro payload é rejeitado');
select throws_ok($$select pg_temp.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000032','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'em_execucao',true)$$,'23514','conflito_ja_resolvido','outro pedido não resolve a mesma ocorrência novamente');
select is((select count(*)::int from pcm.reconciliacao_webhook_chamado_decisoes),1,'retry não duplica decisão');
select is((select count(*)::int from audit.events where entity_id='18593000-0000-4000-8000-000000000021' and action='integracao.resolucao_conflito_webhook'),1,'decisão auditada uma vez');
select throws_ok($$select pcm.sso_resolver_conflito_webhook_chamado('18593000-0000-4000-8000-000000000031','18593000-0000-4000-8000-00000000000a',(select id from pcm.reconciliacao_webhook_chamado_conflitos limit 1),(select coalesce(updated_at,created_at) from pcm.ordens_servico where id='18593000-0000-4000-8000-000000000021'),18593000,'em_execucao',true)$$,'55000','resolucao_conflito_bloqueada','comando operacional mantém gate fechado');
select ok(not has_table_privilege('authenticated','pcm.reconciliacao_webhook_chamado_decisoes','insert') and not has_table_privilege('service_role','pcm.reconciliacao_webhook_chamado_decisoes','update'),'tabela de decisões não tem escrita direta');
select lives_ok($$select pg_temp.sso_registrar_conflito_webhook_chamado('18593000-0000-4000-8000-000000000021',18593000,'em_execucao')$$,'entrega após resolução gera outra condição sem presumir identidade');
select is((select count(*)::int from pcm.reconciliacao_webhook_chamado_conflitos where resolvido_em is null),1,'nova condição permanece aberta');
select is((select count(*)::int from pcm.reconciliacao_webhook_chamado_conflitos where resolvido_em is not null),1,'histórico da condição resolvida permanece');
select throws_ok($$select pcm.sso_registrar_conflito_webhook_chamado('18593000-0000-4000-8000-000000000021',18593000,'em_execucao')$$,'55000','captura_conflito_bloqueada','gate real permanece fechado');
select ok(not has_function_privilege('authenticated','pcm.sso_registrar_conflito_webhook_chamado(uuid,bigint,text)','execute') and has_function_privilege('service_role','pcm.sso_registrar_conflito_webhook_chamado(uuid,bigint,text)','execute'),'somente service_role pode executar captura');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='pcm.reconciliacao_webhook_chamado_conflitos'::regclass),'conflitos com RLS FORCE');
select ok(not has_table_privilege('service_role','pcm.reconciliacao_webhook_chamado_conflitos','insert') and not has_table_privilege('service_role','pcm.reconciliacao_webhook_chamado_conflitos','update'),'service_role não altera conflito diretamente');
select ok(not has_table_privilege('authenticated','pcm.reconciliacao_webhook_chamado_conflitos','select'),'usuário não lê tabela diretamente');
select is((select count(*)::int from pcm.auvo_sync_outbox where row_id='18593000-0000-4000-8000-000000000021'),0,'sem intenção Auvo');
select set_config('request.jwt.claims','{"sub":"18593000-0000-4000-8000-000000000099","role":"authenticated"}',true);
select throws_ok($$select * from pg_temp.sso_listar_os_reconciliacao('18593000-0000-4000-8000-00000000000a',null,50)$$,'42501','cliente_nao_encontrado_ou_sem_acesso','leitura exige autorização');
select throws_ok($$select * from pg_temp.sso_listar_conflitos_webhook_autorizado('18593000-0000-4000-8000-00000000000a','18593000-0000-4000-8000-000000000021',null,null,50)$$,'42501','os_nao_encontrada_ou_sem_acesso','wrapper mediado rejeita usuário sem acesso');
select * from finish();
rollback;
